create or replace function public.set_transport_route_stops(p_route_id uuid, p_stop_ids uuid[]) returns void language plpgsql security invoker set search_path = '' as $$ declare b uuid; key text:=gen_random_uuid()::text; begin if not public.is_transport_admin() then raise exception 'Not authorized' using errcode = '42501'; end if; if not exists (select 1 from public.transport_routes where id=p_route_id) then raise exception 'Route not found'; end if; if cardinality(p_stop_ids) <> (select count(distinct s) from unnest(p_stop_ids) s) then raise exception 'Duplicate stops are not allowed'; end if; delete from public.transport_route_stops where route_id=p_route_id; insert into public.transport_route_stops(route_id, stop_id, position) select p_route_id, stop_id, (ord - 1)::int from unnest(p_stop_ids) with ordinality as u(stop_id,ord); for b in select id from public.transport_buses where route_id=p_route_id loop perform public.route_stops_changed(b,key); end loop; end $$;
create function public.route_stops_changed(p_bus uuid,p_key text) returns void language plpgsql security definer set search_path='' as $$ begin if not public.is_transport_admin() then raise exception 'Not authorized' using errcode='42501'; end if; perform public.emit_bus_notice(p_bus,p_key,'Route stops updated','The stops on your assigned route changed. Check your transport information.','transport'); end $$;
revoke all on function public.route_stops_changed(uuid,text) from public,anon;
grant execute on function public.route_stops_changed(uuid,text) to authenticated;
